import csv
rows=list(csv.reader(open(CATALOG_CSV)))
for r in rows[1:]:
    if 'Power' in r[1] or 'Meter' in r[1] or 'Energy' in r[2] or 'Electric' in r[2]:
        print(r)

import csv
# map zone power sensor URIs to ts ids
zones={}
for r in list(csv.reader(open(CATALOG_CSV)))[1:]:
    if 'Zone_' in r[1] and 'Electric_Power_Sensor' in r[1]:
        zones[r[1]]=r[0]
print(len(zones))
meter='c889cadf-ee1a-5783-816a-c60c58430141'

vals={}
day='2018-07-07'
for r in list(csv.reader(open(VALUES_CSV)))[1:]:
    ts,r0,r1,r2=r[0],r[1],r[2],r[3]
    if r0.startswith(day):
        vals.setdefault(ts,[]).append(float(r1))

build=sum(v for ts,v in vals.items() if ts==meter)
for name,ts in zones.items():
    if ts in vals:
        print(name, sum(vals[ts])*3600)
    else:
        print(name, "NO DATA")
print("building total J:", build)

import csv
zones={}
for r in list(csv.reader(open(CATALOG_CSV)))[1:]:
    if 'Zone_' in r[1] and 'Electric_Power_Sensor' in r[1]:
        zones[r[1]]=r[0]
meter='c889cadf-ee1a-5783-816a-c60c58430141'
needed=set(zones.values())|{meter}
vals={}
day='2018-07-07'
with open(VALUES_CSV) as f:
    rd=csv.reader(f); next(rd)
    for r in rd:
        if len(r)<3 or r[0] not in needed: continue
        if r[1].startswith(day) and r[2]!='':
            vals.setdefault(r[0],[]).append(float(r[2]))
build=sum(vals.get(meter,[]))
light=0
for name,ts in zones.items():
    s=sum(vals.get(ts,[]))*3600
    light+=s
    print(name, s, len(vals.get(ts,[])))
print("building J:", build)
print("lighting J:", light)
print("fraction:", light/build)
